#!/usr/bin/env python3
"""Regenerates src/vertical_orientation_data.inc from the Unicode Character Database file
VerticalOrientation.txt (UAX #50 Vertical_Orientation). Run by a maintainer when the Unicode
version is bumped; the build never runs it.

    python third_party/unicode/gen_vertical_orientation.py third_party/unicode/VerticalOrientation-18.0.0.txt src/vertical_orientation_data.inc

Only the non-default values are written: every code point that is not listed is R (the file's
"@missing: 0000..10FFFF; R" line). Adjacent ranges with the same value are merged.
"""
import hashlib, re, sys

def main(source, target):
    raw = open(source, 'rb').read()
    name = re.search(rb'^# (VerticalOrientation-[\d.]+\.txt)', raw, re.M).group(1).decode()
    entries = []
    for line in raw.decode('utf-8').splitlines():
        line = line.split('#', 1)[0].strip()
        if not line:
            continue
        span, value = [part.strip() for part in line.split(';')]
        first, _, last = span.partition('..')
        first = int(first, 16)
        last = int(last or first, 16) if '..' in span else first
        if value == 'R':
            continue
        if entries and entries[-1][2] == value and entries[-1][1] + 1 == first:
            entries[-1][1] = last
        else:
            entries.append([first, last, value])
    out = [
        '// Generated by third_party/unicode/gen_vertical_orientation.py; do not edit by hand.',
        f'// Source: {name} (Unicode Character Database, UAX #50 Vertical_Orientation)',
        f'// SHA256: {hashlib.sha256(raw).hexdigest()}',
        '// Code points that are not listed are R (rotated).',
    ]
    for first, last, value in entries:
        out.append('{0x%X, 0x%X, VerticalOrientation::%s},' % (first, last, value))
    open(target, 'w', newline='\n').write('\n'.join(out) + '\n')

main(*sys.argv[1:3])
